{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Camellianin B, a flavonoid glycoside, was detected in rat brain after intragastric administration of camellianin A, directly demonstrating that polar flavonoid glycosides can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Cyanidin-3-O-glucoside was detected in rat brain after blueberry feeding and intravenous administration, providing direct in vivo evidence that anthocyanin glycosides reach the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Intact cyanidin 3-galactoside was found in pig brain, supporting brain entry of glycosylated polyphenols in a large-animal model relevant to human absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Hyperoside and related glycosides were detected in rat brain after oral administration of a leaf extract, showing that flavonoid glycosides can achieve brain exposure after systemic absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A phenylethanoid glycoside was detected in rat hippocampus and striatum after oral administration, confirming that highly polar glycosides can pass through the BBB into brain parenchyma.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Deacetyl asperulosidic acid methyl ester, an iridoid glycoside, was detected in rat brain microdialysates and tissue homogenates, providing direct evidence that glycosides can cross the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Although the query is a highly polar flavonoid C-glucoside with unfavorable passive-diffusion properties, multiple high-transfer in vivo studies show that flavonoid, anthocyanin, phenylethanoid, and iridoid glycosides can cross the BBB and reach brain tissue after systemic administration. The query shares the key glycoside and polyphenolic features of these directly measured brain-penetrant compounds, so meaningful CNS access is supported.",
  "evidence_gaps": [
    "No direct experimental measurement exists for the exact query C-glucoside, so quantitative brain concentrations and unbound exposure are not established.",
    "C-glucoside metabolic stability and transporter interactions may differ from the O-glycosides in the supporting evidence.",
    "The extent of brain uptake may be low or transporter-limited, but the label only requires meaningful CNS access, which the direct detection evidence supports."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

